  --user-bg: #eff6ff;
  --assistant-bg: #ffffff;
  --tool-bg: #f9fafb;
  --bg-subtle: rgba(0,0,0,0.03);
  /* Elevated dialogs and high-density tools never inherit skin translucency. */
  --bg-elevated: #ffffff;
  --bg-tool-solid: #ffffff;

  /* Shared control radius / action-tag / icon-flow tokens (static borders; motion only on SVG strokes). */
  --control-radius: 8px;
  --control-radius-sm: 6px;
  --control-radius-pill: 999px;
  --control-motion-fast: 140ms;
  --icon-flow-ambient: 4.8s;
  --icon-flow-interactive: 1.55s;
  --icon-flow-active: 1.25s;
  --icon-flow-dash: 9 34;
  --icon-flow-travel: -43;
  --icon-flow-a: #38bdf8;
  --icon-flow-b: #2563eb;
  --icon-flow-c: #a78bfa;

  /*
