   * Panel surface, center text, and status copy must follow theme — never fixed night colors.
   */
  --usage-panel-surface: color-mix(in srgb, var(--bg-panel) 92%, #ffffff 8%);
  --usage-panel-surface-elevated: color-mix(in srgb, var(--bg) 88%, #ffffff 12%);
  --usage-panel-surface-subtle: color-mix(in srgb, var(--bg-subtle) 70%, transparent);
  --usage-panel-border: color-mix(in srgb, var(--border) 88%, var(--text-muted) 12%);
  --usage-panel-shadow: 0 12px 36px rgba(15, 23, 42, 0.12);
  --usage-panel-close-bg: var(--bg-hover);
  --usage-panel-close-hover: var(--bg-selected);
  --usage-segment-bg: color-mix(in srgb, var(--bg-subtle) 80%, transparent);
  --usage-column-bg: color-mix(in srgb, var(--bg) 96%, var(--bg-panel) 4%);
  --usage-column-header-bg: color-mix(in srgb, var(--bg-subtle) 90%, transparent);
  --usage-card-bg: color-mix(in srgb, var(--bg) 94%, var(--bg-panel) 6%);
  --usage-center-bg: var(--bg-panel);
  --usage-center-label: var(--text);
  --usage-center-value: color-mix(in srgb, var(--text) 78%, var(--text-muted) 22%);
  --usage-status-success-fg: #15803d;
  --usage-status-success-bg: rgba(34, 197, 94, 0.10);
  --usage-status-success-border: rgba(34, 197, 94, 0.32);
  --usage-status-warning-fg: #b45309;
  --usage-status-warning-bg: rgba(245, 158, 11, 0.10);
  --usage-status-warning-border: rgba(245, 158, 11, 0.34);
  --usage-status-danger-fg: #b91c1c;
  --usage-status-danger-bg: rgba(239, 68, 68, 0.08);
  --usage-status-danger-border: rgba(239, 68, 68, 0.28);
  --usage-status-info-fg: color-mix(in srgb, var(--text) 72%, var(--accent) 28%);
  --usage-status-info-bg: color-mix(in srgb, var(--accent) 8%, transparent);
  --usage-status-info-border: color-mix(in srgb, var(--accent) 28%, var(--border) 72%);
  --usage-active-fg: #15803d;
  --usage-dot-success: #16a34a;
  --usage-dot-warning: #d97706;
  --usage-dot-danger: #dc2626;
  --usage-dot-muted: var(--text-dim);
  --provider-usage-ring-layer-0: #06b6d4;
  --provider-usage-ring-layer-1: #8b5cf6;
  --provider-usage-ring-layer-2: #db2777;
  --provider-usage-ring-warning: #d97706;
  --provider-usage-ring-danger: #dc2626;
}

